//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

    app.UserMessageItemView = Backbone.View.extend({

        tagName: 'article',
        className: 'message-discussion',
        template: _.template( ($('#comment-discussion-tpl').html() || '') ),
        events: {
            'click .on-remove-comment': 'onHide'
        },

        /**
        * Constructor Method
        */
        initialize : function(){

            //Init Attributes
            this.$modalBase = $('#modal-base-tp');

            // Init Attributes
            this.configAlert = {
                'wrapper': '#main-wrap',
                'closeTime': 6000,
                'speedOpen': 500,
                'speedClose': 500
            };

            // Events Listener
            this.listenTo( this.model, "change", this.render );
            this.listenTo( this.model, 'destroy', this.remove );
            this.listenTo( this.model, 'request', this.loadSpinner );
            this.listenTo( this.model, 'sync', this.responseServer );

        },

        /*
        * Render View Element
        */
        render: function () {
            var attributes = this.model.toJSON();

            // assign attribute to the element
            this.$el.attr('data-owner', this.model.get('owner'));

            this.$el.html( this.template(attributes) );

            //Initialize Reference to elements

            return this;
        },

        /**
        * hides contacts user
        */
        onHide: function (e) {
            e.preventDefault();

            this.confirmHide = new app.ConfirmWindow({
                model: this.model,
                parameters: {
                    titleConfirm: 'Eliminar mensaje',
                    template: _.template( ($('#confirm-remove-discussion-tpl').html() || '') ),
                    dataFilter: {
                        'codigo_discucion': this.model.get('codigo_discucion'),
                        'codigo_comentario': this.model.get('codigo_comentario')
                    }
                }
            });
            this.confirmHide.render();
        },

        /*
        * Remove View Element
        */
        remove: function(){
            var _this = this;

            this.$el.fadeOut('normal', function (){
                _this.$el.remove();
            });
        },

        /**
        * Load spinner on the request
        */
        loadSpinner: function () {

            window.Misc.setSpinner( this.$el );
        },

        /**
        * response of the server
        */
        responseServer: function (target, resp, opts) {

            var $formComment = this.$el.parents('#user-discussion-message-wrap').find('#form-comment-discussion');

            // response success or error
            var text = !resp.success ? resp.errors: '',
                type = resp.success ? 'success' : 'alert';


            if( _.isObject(resp.errors) ){

                var listError = '<ul>';

                $.each(resp.errors, function(field, item) {
                     listError += '<li>'+ item[0] +'</li>';
                });
                listError += '</ul>';

                text = listError;
            }

            var config = {
                'text': text,
                'type': type
            };
            _.extend( this.configAlert, config );

            //complete proccess
            window.Misc.removeSpinner({
                'wrap': this.$el,
                'direct': true,
                'callback': (function (conf, re, $formReset) {
                    return function () {

                        if( !re.success )
                            window.Misc.showAlertBox( conf );

                        if( re.success ){
                            $formReset[0].reset();
                            $formReset.find(':submit').removeClass('disabled');
                        }
                    }
                })(this.configAlert, resp, $formComment)
            });
        }
    });

})(jQuery, this, this.document);

/**
* Class UserProductListView of Backbone View
* @author TuProyecto || Desarrollador : @xindykatalina
* @link http://TuProyecto.com
*/

//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

    app.UserProductListView = Backbone.View.extend({

        el: '#user-product',
        events: {
            //
        },
        parameters: {
            dataFilter: {}
        },

        /**
        * Constructor Method
        */
        initialize : function(opts){
            _.bindAll(this, 'onLoadMore');

            // extends parameters
            if( opts !== undefined && _.isObject(opts.parameters) )
                this.parameters = $.extend({},this.parameters, opts.parameters);

            //Init Attributes
            this.pageOld = this.collection.state.currentPage;
            this.$spinnerPosts = $('<div>').attr('id','spinner-load-posts');

            // Events Listeners
            this.listenTo( this.collection, 'add', this.addOne );
            this.listenTo( this.collection, 'reset', this.addAll );
            this.listenTo( this.collection, 'request', this.loadSpinner);
            this.listenTo( this.collection, 'sync', this.responseServer);
            this.on('getdata', this.getFirstData);

            $( window ).off("scroll");
            $( window ).on("scroll", this.onLoadMore);

        },

        /*
        * Render View Element
        */
        render: function(){

            // initialize reference
            this.$postsWrap = this.$('#user-product-list');
            this.$noResults = this.$('.no-results-filter');
        },

        /**
        * get reset data
        * @param dataFilter Object
        * @param replace Boolean
        */
        getFirstData: function  (dataFilter, replace) {

            dataFilter || (dataFilter = {});
            replace || (replace = false);

            if(replace) {
                this.parameters.dataFilter = dataFilter;
            }else{
                _.extend( this.parameters.dataFilter, dataFilter );
            }

            this.collection.getFirstPage( {reset:true, data:_.clone(this.parameters.dataFilter)} );
            this.pageOld = this.collection.state.currentPage;
        },

        /**
        * Render view comment by model
        * @param Object marketPlaceModel Model instance
        */
        addOne: function (marketPlaceModel) {

           var view = new app.UserProductItemView({
                model: marketPlaceModel,
                attributes: this.dataFilter
            });

            this.$postsWrap.append( view.render().el );

            if( this.collection.indexOf(marketPlaceModel) >= (this.collection.length - 1)) {

                if( typeof window.initComponent.configEllipsis == 'function' ) {
                    window.initComponent.configEllipsis();
                }
            }
        },

        /**
        * Render all view Marketplace of the collection
        */
        addAll: function () {

            this.$postsWrap.html('');
            this.collection.forEach( this.addOne, this );
        },

        /**
        * Load spinner on the request
        */
        loadSpinner: function ( target, xhr, opts ) {

            if( Backbone.Collection.prototype.isPrototypeOf(target) ){
                this.$spinnerPosts.appendTo( this.$el );
                window.Misc.setSpinner( this.$spinnerPosts );
            }
        },

        /**
        * response of the server
        */
        responseServer: function ( target, resp, opts ) {

            if( target instanceof Backbone.Collection && !target.length ){
                this.$noResults.fadeIn('fast');
            }else {
                this.$noResults.css('display', 'none');
            }

            window.Misc.removeSpinner({
                'wrap': this.$el,
                'direct': false,
                'callback': (function ($elSpinner) {
                    return function () {
                        $elSpinner.remove();
                    };
                })(this.$spinnerPosts)
            });

            window.Misc.removeSpinner({'wrap': this.$postsWrap})
        },


        /**
        * load more posts
        */
        onLoadMore: function (e) {

            e.preventDefault();
            var _this = this;

            var scrollHeight = $(document).height();
            var scrollPosition = $(window).height() + $(window).scrollTop();

            if ((scrollHeight - scrollPosition) / scrollHeight <= 0.001) {

                // when scroll to bottom of the page
                if( this.collection.state.currentPage < this.collection.state.lastPage && this.pageOld == this.collection.state.currentPage ){

                    this.collection.getNextPage({
                        data: _.clone(this.parameters.dataFilter),
                        wait: true,
                        success: function (collection) {
                            _this.pageOld = collection.state.currentPage;
                        }
                    });
                }
            }
        }
   });

})(jQuery, this, this.document);

