app || (app = {});

(function ($, window, document, undefined) {

    app.CourseThemeListView = Backbone.View.extend({

        el: '#course-content',
        attributes: {
            'viewTheme' : 'CourseThemesView'
        },
        events: {

        },

        /**
        * Constructor Method
        */
        initialize : function(){
            // Init Attributes

            // Events Listener
            this.listenTo( this.collection, 'add', this.addOne );
            this.listenTo( this.collection, 'reset', this.addAll );
            this.listenTo( this.collection, 'request', this.loadSpinner );
            this.listenTo( this.collection, 'sync', this.responseServer );
            this.listenTo( this.collection, 'all', this.render );

            if( _.has($.fn, 'foundation') ){
                this.$el.foundation('accordion', {content_class:'content-theme'});
            }
        },

        /*
        * Render View Element
        */
        render: function(){
            // Init Attributes
            this.$themeCourseData = this.$('.themes-course');

            this.$el.foundation('accordion', 'reflow');

            return this;
        },

        /**
        * Render view theme per model
        * @param Object courseThemeModel Model instance
        */
        addOne: function (courseThemeModel) {
            var view = new app[this.attributes.viewTheme]({
                model: courseThemeModel,
                attributes: (_.isObject(this.attributes) && this.attributes.type != undefined) ? {type: this.attributes.type} : {}
            });

            this.$themeCourseData.append( view.render().el );
        },

        /**
        * Render all view category of the collection
        */
        addAll: function () {
            this.$themeCourseData.html();
            this.collection.forEach( this.addOne, this );
        },

        /**
        * Load spinner on the request
        */
        loadSpinner: function () {
            window.Misc.setSpinner( this.$el );
        },

        /**
        * response of the server
        */
        responseServer: function ( model, resp, opts ) {
            window.Misc.removeSpinner({
                'wrap': this.$el,
                'direct': true
            });
        }

   });

})(jQuery, this, this.document);

/**
* Class CourseClassView extend of Backbone View
* @author TuProyecto || Desarrollador : @xindykatalina, @refo44
* @link http://TuProyecto.com
*/

//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

    app.CourseClassView = Backbone.View.extend({

        el: '#course-content',
        template: _.template( ($('#course-course-theme-lecture-tpl').html() || '') ),
        templatePlayer: _.template( ($('#course-lecture-video-tpl').html() || '') ),
        template_navbar: _.template( ($('#learn-navbar').html() || '') ),
        events: {
            'click .prev-video': 'onPrevVideo',
            'click .next-video': 'onNextVideo'
        },
        parameters: {},
        player: null,
        currentTheme: {},
        currentLecture: {},

        /**
        * Constructor Method
        */
        initialize : function(opts){
            _.bindAll(this, 'beforeRender', 'render', 'afterRender', 'readyPlayer');
            // extends parameters
            if( opts !== undefined && _.isObject(opts.parameters) ) {
                this.parameters = _.extend({}, this.parameters, opts.parameters );
            }

            // Init Attributes
            this.courseThemeList = new app.CourseThemeList();
            this.discussionList = new app.DiscussionList();
            this.courseAttachmentsList = new app.CourseAttachmentsList();
            this.userNotesList = new app.UserNotesList();

            var _this = this;
            this.render = _.wrap(this.render, function(render) {

                _this.trigger('beforeRender');

                render();

                _this.trigger('afterRender');

                return _this;
            });

            // Events Listener
            this.listenTo( this.courseThemeList, 'changeVideo', this.changeVideo );
            this.listenTo( this.model, "change", this.render );
            this.on( 'beforeRender', this.beforeRender );
            this.on( 'afterRender', this.afterRender );
        },

        /*
        * Render View Element
        */
        render: function() {
            var _this = this,
                attributes = this.model.toJSON();

            if( _.isObject(this.parameters) && this.parameters.type !== undefined ){
                attributes.type = this.parameters.type;
            }
            this.$el.html( this.template_navbar(attributes));
            this.$el.append( this.template(attributes) );

            // initialize elements
            this.$themesCourse = this.$('#side-course-themes');
            this.$lectureVideo = this.$('#course-lecture-video');
            this.$wrapperDiscussion = this.$('#wrapper-lecture-discussion');
            this.$wrapperAttached = this.$('#side-course-attachments');
            this.$wrapperUserNote = this.$('#side-course-notes');
            this.$titleCourse = this.$('#title-lecture-main');
            this.$descriptionCourse = this.$('#description-lecture-main');
        },

        /**
        * Fires before of run render function
        */
        beforeRender: function() {
        },

        /**
        * Fires after of run render function
        */
        afterRender: function() {
            // reference to views
            this.refenrenceToTabs();

            // initialize dependencies
            this.ready();
        },

        /**
        * reference to tabs's views
        */
        refenrenceToTabs: function () {

            var _this = this;

            // instance course themes
            this.courseThemeListView = new app.CourseThemeListView({
                el: this.$themesCourse,
                collection: this.courseThemeList,
                attributes: {
                    'type': this.parameters.type,
                    'viewTheme': 'CourseThemeClassItemView'
                }
            });

            // intance of discussion view
            this.discussionListView = new app.DiscussionListView({
                el: this.$wrapperDiscussion,
                collection: this.discussionList,
                parameters: {
					'formDiscussion': '#form-discussion-course',
                    dataFilter: {
                        'codigo_recurso_modulo': this.model.get('codigo_curso'),
                        'codigo_modulo': window._tp.getModule('learn')
                    }
                    // 'viewDiscussion': 'DiscussionPostClassView',
                    // 'viewDiscussionComment': 'DiscussionCommentClasstView'
                }
            });

            // intance of attached view
            this.courseAttachedListView = new app.CourseAttachedListView({
                el: this.$wrapperAttached,
                collection: this.courseAttachmentsList,
                parameters: {
                    'course': this.parameters.course
                }
            });

            // intance of usernotes view
            this.userNoteListView = new app.UserNoteListView({
                el: this.$wrapperUserNote,
                collection: this.userNotesList,
                parameters: {
                    'course': this.parameters.course
                }
            });
            // fecth course themes
            this.courseThemeList.fetch({
                data: { 'course': this.parameters.course, 'content': true, 'advance': true },
                reset: true,
                success: function (collection, resp, opts) {
                    var lecture = _this.courseThemeList.getLecture( _this.parameters.course, _this.parameters.theme, _this.parameters.lecture );
                    var model = _this.courseThemeList.findWhere( {'url_tema_curso': _this.parameters.theme} );

                    _this.changeVideo(lecture, model);
                }
            });
        },

        /**
        * fires libraries js and functions
        */
        ready: function () {
            // trigger libraries
            if(_.has($.fn, 'foundation')) {
                this.$el.foundation('abide');
                $(document).foundation('tab', 'reflow');
            }

            // trigger functions
            if( typeof window.initComponent.configScrollbar == 'function' )
                window.initComponent.configScrollbar();
        },

        /**
        * listener when select video
        * @param Object lecture
        */
        changeVideo: function (lecture, model) {

            console.log('lecture',lecture);
            console.log('model', this.model);
            
            var srcVideo = lecture !== undefined ? lecture.direccion_adjunto + (lecture.includeparams || '') : '';

            console.log('srcVideo',srcVideo);

            var attributes = {
                src:  window.Misc.convertVideoEmbed( srcVideo, 'watch' ),
                codigo_tipo_adjunto: typeof lecture !== 'undefined' ? lecture.codigo_tipo_adjunto : null
            };



            if( typeof lecture !== 'undefined' && lecture.codigo_tipo_adjunto == 9 ){
                attributes['src'] = window.Misc.urlFull( Route.route('aprende.curso.tema.formulario',{'type': this.model.get('url_tipo_curso'), 'category': this.model.get('url_categoria_curso'), 'course': this.model.get('url_curso'), 'survey': srcVideo}) ) ;
            }
           
            console.log('attributes',attributes);
            // attributes.src = 'https://www.youtube.com/watch?v=ToWE4stiSC0';
            // attributes.codigo_tipo_adjunto = 2;

            this.$titleCourse.html(model.attributes.nombre_tema_curso);
            this.$descriptionCourse.html(model.attributes.objetivo_tema_curso);
            this.$lectureVideo.html( this.templatePlayer(attributes) );

            // reference to video player
            this.$playerVideo = this.$('#player-video-lecture');
            var typeAttachedVideo = [ window._tp.getTypeAttached['youtube'], window._tp.getTypeAttached['vimeo'] ]; 

            // video player object
           if( _.contains( typeAttachedVideo  ,  attributes['codigo_tipo_adjunto'] ) ){

                this.player = new MediaElementPlayer(this.$playerVideo[0], {
                    pluginPath: window.Misc.urlFull('js/vendor/'),
                    plugins: ['flash','silverlight','youtube','vimeo'],
                    enablePluginDebug: true,
                    alwaysShowControls: true,
                    videoVolume: 'horizontal',
                    features: ['playpause','volume','current','duration','progress','fullscreen','woopraanalytics'],
                    success: this.readyPlayer
                });
            }

            this.currentLecture = lecture;
            this.currentTheme = model;

            model.trigger('active', model, lecture);
        },

        /**
        *
        */
        readyPlayer: function (media, element) {
            // 'https://img.youtube.com/vi/' + this.url.videoId + '/maxresdefault.jpg';

            var _this = this;
            this.listenTo(media, 'trackViewed', this.trackViewed);

            media.addEventListener('ended', function (e) {
                $courseAttachment = new app.CourseThemeAttachedModel();
                $courseAttachment.idAttribute = 'url_adjunto';

                if(_this.currentLecture.state_review !== true)
                {
                    $courseAttachment.save({'_token': $('meta[name="csrf-token"]').attr('content'),
                        'url_adjunto':_this.currentLecture.url_adjunto,
                        'srcparams': _this.currentLecture.srcparams
                    }, {type : 'PATCH'});
                }

                _this.swapVideo('next');
            }, false);

            media.addEventListener('volumechange', function (e) {
                console.log('volumechange::', media.volume, media.muted);
            }, false);

            media.play();
        },

        /**
        * previous video
        */
        onPrevVideo: function (e) {
            e.preventDefault();

            this.swapVideo('prev');
        },

        /**
        * next video
        */
        onNextVideo: function (e) {
            e.preventDefault();

            this.swapVideo('next');
        },

        /**
        * track viewed of video
        * @param Numeric timeInterval
        * @param String interval
        */
        trackViewed : function (timeInterval, interval) {
            var hasRequirements = ( (_.isString(this.currentTheme.get('url_curso')) && this.currentTheme.get('url_curso').length)
                && (_.isString(this.currentTheme.get('url_tema_curso')) && this.currentTheme.get('url_tema_curso').length)
                && (_.isString(this.currentLecture.url_adjunto) && this.currentLecture.url_adjunto.length) );

            if(hasRequirements && typeof woopra != 'undefined') {
                woopra.track('viewedvideo', {
                    course: this.model.get('url_curso'),
                    coursename: this.model.get('nombre_curso'),
                    theme: this.currentTheme.get('url_tema_curso'),
                    themename: this.currentTheme.get('nombre_tema_curso'),
                    video: this.currentLecture.url_adjunto,
                    videoname: this.currentLecture.nombre_adjunto,
                    interval: interval,
                    time: timeInterval
                });
            }
        },


        /**
        * swap video lecture
        * @param String direction
        */
        swapVideo: function (direction) {

            direction || (direction = 'next');

            var oldLecture = this.currentLecture,
                nextLecture = null,
                oldTheme = this.currentTheme,
                nextTheme = null,
                inDoc = null,
                count = direction == 'prev'? -1 : 1;

            // select next video of theme
            if( !(_.isEmpty(this.currentTheme) && _.isEmpty(this.currentLecture)) ) {

                oldLecture = _.findWhere(this.currentTheme.get('adjuntos'), {url_adjunto: this.currentLecture.url_adjunto});
                nextLecture = this.currentTheme.get('adjuntos')[ _.indexOf(this.currentTheme.get('adjuntos'), oldLecture) + count ];
            }

            // select next theme, whenever theme does not have more next video
            if( _.isUndefined(nextLecture) ) {
                nextTheme = this.courseThemeList.at( this.courseThemeList.indexOf(this.currentTheme) + count );

                if( nextTheme !== undefined && _.isArray(nextTheme.get('adjuntos')) && nextTheme.get('adjuntos').length ){

                    nextLecture = direction == 'prev' ? _.last(nextTheme.get('adjuntos')) : _.first(nextTheme.get('adjuntos'));

                    inDoc = window.Misc.codInDoc( nextLecture['codigo_tipo_adjunto'] );

                    if( inDoc != -1 || (nextLecture['codigo_tipo_adjunto'] == window._tp.getTypeAttached['link']) ) {

                        this.currentLecture = nextLecture;
                        this.currentTheme = nextTheme;
                        this.swapVideo(direction);

                    }else {
                        this.changeVideo( nextLecture, nextTheme );

                        app.AppRouter.navigate( Route.route('aprende.curso.tema.clase', {'type': this.parameters.type, 'category': this.model.get('url_categoria_curso'), 'course': this.model.get('url_curso'), 'theme': nextTheme.get('url_tema_curso'), 'class': nextLecture.url_adjunto}), {trigger: false} );
                    }
                }

            }else {

                inDoc = window.Misc.codInDoc( nextLecture['codigo_tipo_adjunto'] );

                if( inDoc != -1 || (nextLecture['codigo_tipo_adjunto'] == window._tp.getTypeAttached['link']) ) {

                    this.currentLecture = nextLecture;
                    this.currentTheme = oldTheme;
                    this.swapVideo(direction);

                }else {
                    this.changeVideo(nextLecture, oldTheme);

                    app.AppRouter.navigate( Route.route('aprende.curso.tema.clase', {'type': this.parameters.type, 'category': this.model.get('url_categoria_curso'), 'course': this.model.get('url_curso'), 'theme': oldTheme.get('url_tema_curso'), 'class': nextLecture.url_adjunto}), {trigger: false} );
                }
            }
        }
   });

})(jQuery, this, this.document);

