//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

    app.CourseThemesView = Backbone.View.extend({
        tagName: 'li',
        className: 'accordion-navigation-theme active',
        template: _.template( ($('#course-themes-list-tpl').html() || '') ),
        events: {
            //
        },

        /**
        * Constructor Method
        */
        initialize: function(){

            //Init Attributes

            // Events Listener
            this.listenTo( this.model, "change", this.render );
        },

        /*
        * Render View Element
        */
        render: function(){

        	var attributes = this.model.toJSON();
            if( _.isObject(this.attributes) && this.attributes.type !== undefined ){
                attributes.type = this.attributes.type;
            }

            this.$el.html( this.template(attributes) );

            return this;
        }

    });

})(jQuery, this, this.document);

/**
* Class CourseThemeAttachedView extends of Backbone View
* @author TuProyecto || Desarrollador : @xindykatalina
* @link http://TuProyecto.com
*/

//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

    app.CourseThemeAttachedView = Backbone.View.extend({
        tagName: 'li',
        className: '',
        events: {
            'click .change-viewed': 'onChangeStateAttached',
            'click .link-to-theme-article': 'onActivateStateAttached'
        },

        initialize: function () {
            //Init Attributes
            this.stateAttachedTheme = this.$('.state-attached-theme');

            // Events Listener
            this.listenTo( this.model, 'sync', this.responseServer );

        },

        /**
        *
        */
        onChangeStateAttached: function (e) {
            this.model.changeStateReview();
        },

        /**
         *
         */
        onActivateStateAttached: function (e) {

            if(this.model.get('state_review') !== true) {
                this.model.changeStateReview();
            }

        },

        responseServer: function (target, resp, opts) {

            if( resp.success ){

                // whenever change the review state
                if( this.model.changed['state_review'] ){
                    this.stateAttachedTheme.removeClass('gray-light')
                                           .addClass('success');
                }else{
                    this.stateAttachedTheme.removeClass('success')
                                           .addClass('gray-light');
                }
            }
        }
    });

})(jQuery, this, this.document);

/**
* Class CourseUnsubscribeConfirmView extends of Backbone View
* @author TuProyecto || Desarrolladora : @cindykatalina
* @link http://TuProyecto.com
*/

//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

    app.CourseUnsubscribeConfirmView = Backbone.View.extend({

        el: '#modal-base-confirm-tp',
        template: _.template( ($('#course-confirm-unsubscribe-tpl').html() || '') ),
        parameters: {
        	'titleConfirm': '',
            'inscripcion': '',
            'course': ''
        },

        /**
        * Constructor Method
        */
        initialize : function(opts) {
        	
        	// extends attributtes
        	_.extend( this.parameters, opts.parameters );

        	// Init Attributes
        },

        /*
        * Render View Element
        */
        render: function() {
        	var attributes = {};
            this.$el.find('.content-modal').html( this.template(attributes) );

            // Change modal title
            this.$el.find('.inner-title-modal').html( this.parameters['titleConfirm'] );
            this.$el.foundation('reveal', 'open');

        	// delegate events
        	$(this.el).off();
            this.delegateEvents({
            	'click .confirm-action': 'onConfirm'
            });

            return this;
        },

        /**
        * Event Close Confirm
        */
        onConfirm: function (e) {
            e.preventDefault();
            this.$el.foundation('reveal', 'close');
            this.model.destroy({
                processData: true,
                wait: true,
                data: {
                    'inscripcion': this.parameters['inscripcion'],
                    'course': this.parameters['course'],
                    '_token': $('meta[name="csrf-token"]').attr('content') 
                }
            });
        }
   });

})(jQuery, this, this.document);

/**
* Class CourseAttachedListView of Backbone View
* @author TuProyecto || Desarrollador : @xindykatalina
* @link http://TuProyecto.com
*/

//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

    app.CourseAttachedListView = Backbone.View.extend({

        el: '#side-course-attachments',
        events: {
            //
        },
        parameters: {
            course: ''
        },

        /**
        * Constructor Method
        */
        initialize : function(opts){
            _.bindAll(this, 'onLoadMore');

            // Extend options parameters
            if( _.isObject(opts.parameters) ){
                _.extend(this.parameters, opts.parameters);
            }

            //Init Attributes
            this.$postsWrap = this.$('#course-attachments-wrap');
            this.$noResults = this.$('.no-results-filter');
            this.$spinnerPosts = $('<div>').attr('id','spinner-load-posts');
            this.pageOld = this.collection.state.currentPage;

            this.dataFilter = {'course': this.parameters['course']};

            // Events Listener
            this.listenTo( this.collection, 'add', this.addOne );
            this.listenTo( this.collection, 'reset', this.addAll );
            this.listenTo( this.collection, 'request', this.loadSpinner);
            this.listenTo( this.collection, 'sync', this.responseServer);
            this.listenTo( this.collection, 'all', this.render);
            this.on('getdata', this.getFirstData);

            $( window ).on("scroll", this.onLoadMore);

            this.trigger('getdata');
        },

        /*
        * Render View Element
        */
        render: function(){
            if( this.collection.length )
                this.$noResults.css('display', 'none');
        },

        /**
        * Render view comment by model
        * @param Object courseAttachedModel Model instance
        */
        addOne: function (courseAttachedModel) {

            var view = new app.CourseAttachedItemView({
                model: courseAttachedModel
            });
            this.$postsWrap.prepend( view.render().el );
        },

        /**
        * Render all view comment of the collection
        */
        addAll: function () {
            
            this.$postsWrap.html('');
            this.collection.forEach( this.addOne, this );
        },

        /**
        * Load spinner on the request
        */
        loadSpinner: function ( target, xhr, opts ) {

            this.$noResults.css('display', 'none');

            if( Backbone.Collection.prototype.isPrototypeOf(target) ){
                this.$spinnerPosts.appendTo( this.$postsWrap );
            }else{
                this.$spinnerPosts.prependTo( this.$postsWrap );
            }
            window.Misc.setSpinner( this.$spinnerPosts );
        },

        /**
        * response of the server
        */
        responseServer: function ( target, resp, opts ) {

            if( !target.length )
                this.$noResults.fadeIn('fast');

            window.Misc.removeSpinner({
                'wrap': this.$el,
                'direct': false,
                'callback': (function ($elSpinner) {
                    return function () {
                        $elSpinner.remove();
                    };
                })(this.$spinnerPosts)
            });

            window.Misc.removeSpinner({'wrap': '#side-course-attachments'})
        },

        /**
        * get reset data
        *
        */
        getFirstData: function  () {
            this.collection.getFirstPage( {reset:true, data: this.dataFilter} );
        },

        /**
        * load more posts
        */
        onLoadMore: function (e) {

            e.preventDefault();
            var _this = this;

            var scrollHeight = $(document).height();
            var scrollPosition = $(window).height() + $(window).scrollTop();

            if ((scrollHeight - scrollPosition) / scrollHeight <= 0.001) {
                // when scroll to bottom of the page
                if( this.collection.state.currentPage < this.collection.state.lastPage && this.pageOld == this.collection.state.currentPage ){

                    this.collection.getNextPage({
                        data: this.dataFilter,
                        wait: true,
                        success: function (collection) {
                            _this.pageOld = collection.state.currentPage;
                        }
                    });
                }
            }
        }
   });

})(jQuery, this, this.document);

