//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

	app.BlogCreateView = Backbone.View.extend({
        el: '#create-article',
		template: _.template( ($('#blog-create-tpl').html() || '') ),
        events:{
			'submit #form-create-article': 'onStore'
		},

        /**
		* Constructor Method
		*/
		initialize : function() {
			_.bindAll(this, 'beforeRender', 'render', 'afterRender');

			//Init Attributes
            this.model = new app.BlogArticleModel();

			this.configAlert = {
				'wrapper': '#main-wrap',
				'closeTime': 6000,
				'speedOpen': 500,
				'speedClose': 500
			};

			var _this = this;
			this.render = _.wrap(this.render, function(render) {

				_this.trigger('beforeRender');

				render();

				_this.trigger('afterRender');

				return _this;
			});

			//Events Listener
			this.listenTo( this.model, 'change:codigo_contenido', this.fetchOne );
			this.listenTo( this.model, 'request', this.loadSpinner );
			this.listenTo( this.model, 'sync', this.responseServer );
			this.on( 'beforeRender', this.beforeRender );
			this.on( 'afterRender', this.afterRender );

			// Events customize
		},

        /*
		* Render View Element
		*/
		render: function(){

			var attributes = {};

			this.$el.html( this.template(attributes) );

			// Initialize attributes
			this.$formCreate = this.$('#form-create-article');
		},

		/**
		* Fires before of run render function
		*/
		beforeRender: function() {
			//
		},

		/**
		* Fires before of run render function
		*/
		afterRender: function() {
			this.ready();
		},

		/**
		* fires libraries js
		*/
		ready: function () {

			var _this = this;

			// trigger libraries
			if( _.has($.fn, 'foundation') ){
				$(document).foundation('abide', 'reflow');
			}

			// reload plugins
			if( _.has($.fn, 'select2') && typeof window.initComponent.select2Trigger == 'function' )
				window.initComponent.select2Trigger();

			if( typeof window.initComponent.initConfigForm == 'function' )
				window.initComponent.initConfigForm();

			if( typeof window.initComponent.initLightBox == 'function' && _.has($.fn, 'imageLightbox') )
				window.initComponent.initLightBox();

			if( typeof window.initComponent.configInputMask == 'function' && _.has($.fn, 'inputmask') )
				window.initComponent.configInputMask();
		},

        /**
		* fetch category of the foro theme and reload on collection view
		* @param Object forumModel model instance
		* @param Object options object hash
		*/
		fetchOne: function (blogModel) {

			if (this.model.changed.codigo_contenido === undefined){
                return;
            }

			app.AppRouter.navigate( Route.route( 'blog.categoria.articulo', { category: blogModel.get('url_tipo_contenido'), article: blogModel.get('url_contenido') }), {trigger: true});
		},

        /**
		* Event Create Forum Post
		*/
		onStore: function (e) {
			e.preventDefault();

			var data = window.Misc.formToJson( e.target );

            if(data.texto_contenido){
                data.texto_contenido = window.Misc.stripTags( data.texto_contenido, 'a' );
                data.texto_contenido = data.texto_contenido.replace(/(\&nbsp;|<[a-z\?\!\/]([a-z0-9\_\:\.])*(\s[^>]*)?(>|$))/gi, ' $&');
                data.texto_contenido = window.Misc.urlWrapLink( data.texto_contenido );
            }

			this.model.save( data, {patch:true, wait:true} );
		},

        /**
		* Load spinner on the request
		*/
		loadSpinner: function (model, xhr, opts) {

			window.Misc.setSpinner( this.$el );
		},

		/**
		* response of the server
		*/
		responseServer: function ( model, resp, opts ) {

			// response success or error
            var type = resp.success ? 'success' : 'alert',
                text = resp.success ?
                        (resp.message !== undefined ? resp.message : '...')
                            : resp.errors;

            if( _.isObject( resp.errors ) ) {

                var listError = '<ul>';

                $.each(resp.errors, function(field, item) {
                     listError += '<li>'+ item[0] +'</li>';
                });
                listError += '</ul>';

                text = listError;
            }

            var conf = {
                'text': text,
                'type': type
            };
            _.extend(this.configAlert, conf);

			//complete proccess
			window.Misc.removeSpinner({
				'wrap': this.$el,
				'direct': false,
				'callback': (function (conf, re, $formReset) {
					return function () {

						window.Misc.showAlertBox( conf );
						if( re.success ){

							$formReset[0].reset()
							$formReset.find('.chosen-select')
									  .trigger("chosen:updated");
						}
					}
				})(this.configAlert, resp, this.$formCreate)
			});
		}
    });

 })(jQuery, this, this.document);

/**
* Class ArticleEdit extends of Backbone View
* @author TuProyecto || Desarrollador : @xindykatalina
* @link http://TuProyecto.com
*/

//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

    app.ArticleEdit = Backbone.View.extend({

        el: '#blog-content',
        events: {
            'click .edit-field': 'onOpenEditForm'
        },

        parameters: {
            //
        },

        /**
        * Constructor Method
        */
        initialize : function(opts) {

            // Extend options parameters
            if( _.isObject(opts.parameters) ){
                _.extend(this.parameters, opts.parameters);
            }

            //Init Attributes
            this.editForms = {
                'infobasic': {'nameView': 'articleEditBasic', 'nameClassView': 'ArticleEditBasic', 'renderTo': '#drop-edit-form'},
                'infodescription': {'nameView': 'articleEditDescription', 'nameClassView': 'ArticleEditDescription', 'renderTo': '#article-infodescription-container .field-editing'}
            };
        },

        /*
        * Render View Element
        */
        render: function() {

            return this;
        },

        /**
        * open edit form
        */
        onOpenEditForm: function (e) {
            e.preventDefault();

            var nameFormTmpl = '',
                $editField = $(e.currentTarget);

            if( $editField.data('edit-template') ) {
                nameFormTmpl = $editField.data('edit-template');
            }

            this.swicthEditForm(nameFormTmpl);
        },

        /**
        * switch for edit forms
        * @param String nameForm
        */
        swicthEditForm: function (nameForm) {

            nameForm || (nameForm = '');

            var _this = this;

            var toRenderView = {
                'infobasic' : function() {
                    _this.renderViewToEdit('infobasic', {
                        parameters: {
                            'dropdown': _this.editForms['infobasic'].renderTo
                        }
                    });
                },
                'infodescription' : function() {
                    _this.renderViewToEdit('infodescription');

                    // React component simple-editor
                    ReactDOM.render(React.createElement(SimpleEditor, {
                        content: _this.model,
                        formCreate: nameForm,
                        value: _this.model.get('texto_contenido'),
                        name: "texto_contenido",
                        options: {
                            placeholder: 'Agrega un contenido',
                            toolbar: [
                                ['font', ['bold', 'italic', 'underline', 'strikethrough', 'clear']],
                                ['para', ['ul', 'ol', 'paragraph', 'height']],
                                ['insert', ['link']]
                            ]
                        }
                    }, null), document.getElementById('form-project-editor'));
                },
                'default' : function() {
                    //
                }
            };

            if (toRenderView[nameForm]) {
                toRenderView[nameForm]();
            } else {
                toRenderView['default']();
            }
        },

        /**
        * to render edit view
        * @param String nameForm
        * @param Object params
        */
        renderViewToEdit: function (nameForm, params) {

            params || (params = {});

            var config = {
                model: this.model
            };
            _.extend( config, params );

            // if it exists form template
            if( this.editForms[nameForm] ) {

                if( this[this.editForms[nameForm].nameView] instanceof Backbone.View ){
                    this[this.editForms[nameForm].nameView].stopListening();
                    this[this.editForms[nameForm].nameView].undelegateEvents();
                }

                if( window.app[this.editForms[nameForm].nameClassView] !== undefined ) {
                    this[this.editForms[nameForm].nameView] = new window.app[this.editForms[nameForm].nameClassView]( config );
                    // set view inside container
                    if( this.editForms[nameForm].renderTo ){
                        this.$(this.editForms[nameForm].renderTo).html( this[this.editForms[nameForm].nameView].render().el );
                    }else {
                        this[this.editForms[nameForm].nameView].render();
                    }

                    // trigger fuctions plugin
                    if( _.has($.fn, 'foundation') ) {
                        // this[this.editForms[nameForm].nameView].$el.foundation('abide');
                    	$(document).foundation('abide', 'reflow');
                    }

                    if( typeof window.initComponent.select2Trigger == 'function' && _.has($.fn, 'select2') ) {
                        window.initComponent.select2Trigger();
                    }

                    if( typeof(window.initComponent.spinnerTrigger) == 'function' && _.has($.fn, 'sspinner') ){
                        window.initComponent.spinnerTrigger();
                    }

                    if( typeof(window.initComponent.configInputMask) == 'function' && _.has($.fn, 'inputmask') ) {
						window.initComponent.configInputMask();
					}

                    // reload plugins
                    if( typeof window.initComponent.initConfigForm == 'function' ) {
                        window.initComponent.initConfigForm();
                    }
                }
            }
        }
    });

})(jQuery, this, this.document);

