/**
* Class FavoriteView extends of Backbone View
* @author TuProyecto || Desarrollador : @krobing
* @link http://TuProyecto.com
*/

//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

	app.FavoriteView = Backbone.View.extend({

		tagName: 'a',
		className: 'TPfavoritelink',
		parameters: {
			'codFavorite': null,
			'favoriteState': false,
			'srcparams': null
		},
		events: {
			'click': 'onChangeState'
		},

		/**
		* Constructor method
		*/
		initialize: function (opts) {
			// Extend parameters custome
			if( opts !== undefined && _.isObject(opts.parameters) )
				this.parameters = _.extend({}, this.parameters, opts.parameters);

			// Initialize attributes
			this.$modalLogin = $('#modal-login');

			// Events Listener
			this.listenTo( this.model, 'change:favorito_auth', this.render );
			this.listenTo( this.model, 'request', this.requestFavorite );
            this.listenTo( this.model, 'sync', this.responseFavorite );

            this.render();
		},

		/**
		* Render view element
		*/
		render: function () {

			// overwrite id attribute of model
           	if( _.isUndefined(this.model.id) && this.parameters.codFavorite) {

        		this.model.set( {codigo_favorito:this.parameters.codFavorite, favorito_auth:this.parameters.favoriteState} );
           	}

           	if( this.model.get('favorito_auth') ) {
           		this.$el.attr('title', 'Quitar de favoritos');
           	}else {
           		this.$el.attr('title', 'Añadir a favoritos');
           	}

           	// switch favorite state
           	this.$el.toggleClass('on-favorite', this.model.get('favorito_auth') );
		},

		/**
		* on change favorite state
		*/
		onChangeState: function (e) {

			e.preventDefault();

			if( window.Misc.checkSession(false) ) {

				if( !this.$el.hasClass('disabled') ) {
					this.model.save({
		                '_token': $('meta[name="csrf-token"]').attr('content'),
		                'srcparams': this.parameters['srcparams'],
		                'favorito_auth': !this.model.get('favorito_auth')
		            }, {patch: true});
				}

			} else {
				this.$modalLogin.foundation('reveal','open');
			}
		},

		/**
		* request favorite of server
		*/
		requestFavorite: function (target, xhr, opts) {

			this.$el.addClass('disabled');
		},

		/**
        * response favorite of server
        */
		responseFavorite: function (target, resp, opts) {

			this.$el.removeClass('disabled');
		}
	});

})(jQuery, this, this.document);

/**
* Class GalleryEditItemView extends of Backbone View
* @author TuProyecto || Desarrollador : @krobing
* @link http://TuProyecto.com
*/

//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

    app.GalleryEditItemView = Backbone.View.extend({
        tagName: 'li',
        className: function () {
        	return 'img-gallery-item-'+ this.cid;
        },
        template: _.template( ($('#gallery-image-item-tpl').html() || '') ),
        events: {
        	'click .change-image-gallery': 'onChangeImage'
        },
        parameters: {
            cod_involved: null
        },

        /**
        * Constructor Method
        */
        initialize: function(opts){
            _.bindAll(this, 'beforeRender', 'render', 'afterRender', 'openModalImg', 'closeModalImg');

            if( opts !== undefined && _.isObject(opts.parameters) )
                this.parameters = $.extend({}, this.parameters, opts.parameters);

            //Init Attributes
            this.$modalImageCrop = $('#modal-image-gallery');

            this.configAlert = {
                'wrapper': '#main-wrap',
                'closeTime': 6000,
                'speedOpen': 500,
                'speedClose': 500
            };

            var _this = this;
            this.render = _.wrap(this.render, function(render) {

                _this.trigger('beforeRender');

                render();

                _this.trigger('afterRender');

                return _this;
            });

            // Events Listener
            this.listenTo( this.model, "change", this.render );
            this.listenTo( this.model, 'change:direccion_adjunto', this.changedImage );
            this.on( 'beforeRender', this.beforeRender );
            this.on( 'afterRender', this.afterRender );

            // Events customize
        },

        /*
        * Render View Element
        */
        render: function(){

            var attributes = this.model.toJSON();
            attributes['editable'] = !!$('.edit-gallery-images:checked').length;

            this.$el.html( this.template(attributes) );

            return this;
        },

        /**
        * Fires before of run render function
        */
        beforeRender: function() {
            //
        },

        /**
        * Fires before of run render function
        */
        afterRender: function() {

            this.ready();
        },

        /**
        * fires libraries js
        */
        ready: function () {

            var _this = this;

            // trigger functions

            this.renderUploaderGalleryImg();
        },

        /**
        * when the image changed
        */
        changedImage: function () {

			var _this = this;

			// replace clone also
			$('.img-gallery-item-'+ this.cid +' > [data-gallery-img="'+ this.$('.item-gallery-image').data('gallery-img') +'"]').each(function(index, el) {

				var attributes = _this.model.toJSON();
				attributes['editable'] = !!$('#edit-gallery-images:checked').length;
				$(el).closest('.slick-cloned').html( _this.template(attributes) );
			});
        },

        // ===============================================================
		//              start of image uploader crop
		// ===============================================================

		/**
		* set image uploader crop
		*/
		renderUploaderGalleryImg: function () {

			var _this = this;

			this.$el.imageUploaderCrop({
				formCrop: $('#form-gallery-crop'),
				imgCrop: $('#image-gallery-tocrop'),
				previewImg: $('#gallery-preview-tocrop'),
				uploaderImg: $('#uploader-image-gallery'),
				templateImgUploader: 'qq-img-uploader-template',
				configImg: {
					maxWidthImg : 646 * 4,
					maxHeightImg : 374 * 4,
					minWidthImg : 646,
					minHeightImg : 374
				},
				uploadding: {
					inputName: 'file',
					endpoint: document.url + Route.route('file.temp'),
					customHeaders: {
						'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content'),
						'X-XSRF-TOKEN': window.Misc.getCsrf().getCookie('XSRF-TOKEN')
					},
					params: {
						'_token': $('meta[name="csrf-token"]').attr('content')
					}
				},
				cropping: {
					endpoint: document.url + Route.route('file.crop'),
					params: {}
				},
				extraDropzones: [_this.$('.image-area-drop'), $('#image-crop-gallery')],
				// Events handlers
				callbacks: {
					onLoadImg: function ($uploaderImg, id, name) {

						var $areaDrop = $uploaderImg.fineUploader('getDropTarget', id);

						if( $areaDrop !== undefined && $areaDrop.length ){
							if( $areaDrop.hasClass('image-area-drop') ){
								_this.$('.change-image-gallery:eq(0)').trigger('click');

								$(document).on('closed.fndtn.reveal', _this.$modalImageCrop, _this.closeModalImg);
								_this.$modalImageCrop.foundation('reveal', 'open');
							}
						}

						window.Misc.setSpinner( _this.$modalImageCrop.find('.content-modal') );
					},
					onCompleteLoad: function ($uploaderImg, id, name, res) {
						$uploaderImg.find('.qq-uploader').css( {'border': 'none'} );

						window.Misc.removeSpinner({
							'wrap': _this.$modalImageCrop,
							'direct': false
						});
					},
					onCropping: function (jcrop_img) {
						window.Misc.setSpinner( _this.$modalImageCrop.find('.content-modal') );
					},
					onCropComplete: function (jcrop_img, resp, jqXHR) {
						// response success or error
						var confCrop = {},
							type = resp.success ? 'success' : 'alert',
							text = resp.success ?
								(resp.message !== undefined ? resp.message : '')
								: resp.errors;

						if( _.isObject( resp.errors ) ){

							var listError = '<ul>';

							$.each(resp.errors, function(field, item) {
								 listError += '<li>'+ item[0] +'</li>';
							});
							listError += '</ul>';

							text = listError;
						}

						var conf = {
							wrapper: _this.$modalImageCrop.find('.content-modal'),
							text: text,
							type: type
						};
						confCrop = $.extend({}, _this.configAlert, conf);

						if( resp.success !== undefined ) {
							if( resp.success ){
								_this.model.set('direccion_adjunto', resp.file_path);

								_this.$modalImageCrop.foundation('reveal', 'close');
							}else{
								window.Misc.showAlertBox( confCrop );
							}
						}

						window.Misc.removeSpinner({
							'wrap': _this.$modalImageCrop,
							'direct': false
						});
					},
					onCropError: function (jcrop_img, jqXHR, error) {
						var confCrop = {},
							conf = {
								wrapper: _this.$modalImageCrop.find('.content-modal'),
								text: 'La imagen no puede ser ajustada.',
								type: 'alert',
								close: true
							};

						confCrop = $.extend({}, _this.configAlert, conf);

						window.Misc.removeSpinner({
							'wrap': _this.$modalImageCrop,
							'direct': false
						});
						window.Misc.showAlertBox( confCrop );
					}
				},
                messages: window._tp.messages
			});
		},

		/**
		* change project image main
		*/
		onChangeImage: function (e) {

			if( e !== undefined )
				e.preventDefault();

			$(document).on('opened.fndtn.reveal', this.$modalImageCrop, this.openModalImg);
			$(document).on('closed.fndtn.reveal', this.$modalImageCrop, this.closeModalImg);

			this.$modalImageCrop.foundation('reveal', 'open');
		},

		/**
		* handler event with avatar modal is opened
		*/
		openModalImg: function (e) {

			var _this = this;

			if( this.$el.data('imageUploaderCrop') !== undefined ) {
				this.$el.imageUploaderCrop('changeImage', this.model.get('direccion_adjunto'));
            }
		},

		/**
		* handler event on crop modal is closed
		*/
		closeModalImg: function (e) {

			if(e.namespace != 'fndtn.reveal') return;

			var $imgCrop = this.$el.imageUploaderCrop('getImgCrop'),
				$imgPreview = this.$el.imageUploaderCrop('getPreviewImg'),
				jcrop_img = null;

			// check out if already was assigned the jcrop library
			if( $imgCrop.data('Jcrop') !== undefined ){
				$imgCrop.attr('src', '');
				$imgPreview.attr('src', '');
				jcrop_img = $imgCrop.data('Jcrop');
				jcrop_img.destroy();
			}

			// detach events
			$(document).off('opened.fndtn.reveal', this.$modalImageCrop);
			$(document).off('closed.fndtn.reveal', this.$modalImageCrop);
		}
    });

})(jQuery, this, this.document);

/**
* Class GalleryListView extends of Backbone View
* @author TuProyecto || Desarrollador : @krobing
* @link http://TuProyecto.com
*/

//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

	app.GalleryListView = Backbone.View.extend({
		el: '#product-gallery-edit',
		events: {
		},
		parameters: {
			viewItemImage: 'GalleryEditItemView',
			codigo_involved: null,
			thumbs: 9,
			dataFilter: {}
		},

		/**
		* Constructor Method
		*/
		initialize : function(opts){

			// Extend options parameters
			if( opts !== undefined && _.isObject(opts.parameters) ){
				this.parameters = $.extend({},this.parameters, opts.parameters);
			}

			//Init Attributes

			// Events Listener
			this.listenTo( this.collection, 'add', this.addOne );
			this.listenTo( this.collection, 'reset', this.addAll );
			this.listenTo( this.collection, 'request', this.loadSpinner);
			this.listenTo( this.collection, 'sync', this.responseServer);
			this.listenTo( this.collection, 'all', this.render);
			this.listenTo( this.collection, 'change', this.changeGallery);

			this.on('getdata', this.getFirstData);
		},

		/*
		* Render View Element
		*/
		render: function(){
			//
		},

		/**
		* get reset data
		*
		*/
		getFirstData: function  (dataFilter, replace) {

			dataFilter || (dataFilter = {});
			replace || (replace = false);

			if(replace) {
				this.parameters.dataFilter = dataFilter;
			}else{
				_.extend( this.parameters.dataFilter, dataFilter );
			}

			this.collection.fetch({ reset:true, data:_.clone(this.parameters.dataFilter) });
		},

		/**
		* Render view comment by model
		* @param Object discussionModel Model instance
		*/
		addOne: function (galleryImageModel) {

			var _this = this;

			var view = new app[ this.parameters.viewItemImage ]({
				model: galleryImageModel,
				parameters: {
					cod_involved: this.parameters.codigo_involved
				}
			});

			// if element content is a carrousel to do another thing
			if( this.$el.hasClass('slick-initialized') ) {

				this.$el.slick('slickAdd', view.render().el );

				// refresh form slick
				window.setTimeout(function () {
					_this.$el.slick('setPosition');
				}, 100);

			}else {
				this.$el.append( view.render().el );
			}

			if( typeof(window.initComponent.initLightBox) == 'function' && _.has($.fn, 'imageLightbox') )
				window.initComponent.initLightBox();
		},

		/**
		* Render all view comment of the collection
		*/
		addAll: function () {

			while( this.collection.length < parseInt(this.parameters.thumbs) ){
				this.collection.push( new app.AttachmentModel(), {silent:true} );
			}

			if( this.$el.hasClass('slick-initialized') ) {
				this.$el.find('.slick-track').html('');
			}else {
				this.$el.html('');
			}

			this.collection.forEach( this.addOne, this );
		},

		/**
		* Load spinner on the request
		*/
		loadSpinner: function ( target, xhr, opts ) {

			window.Misc.setSpinner( this.$el );
		},

		/**
		* response of the server
		*/
		responseServer: function ( target, resp, opts ) {

			// complete process
			window.Misc.removeSpinner({
				'wrap': this.$el,
				'direct': false
			});
		},

		/**
		* change gallery
		*/
		changeGallery: function () {

			var _this = this;

			if( this.$el.hasClass('slick-initialized') ) {

				window.setTimeout(function () {
					_this.$el.slick('setPosition');
				}, 100);
			}
		}
   });

})(jQuery, this, this.document);

